app.use(requestLogger);   // new
app.use("/accounts", accounts);
app.use("/orders", orders);
```

Placing it *after* `sessionUser` means `req.user` is already populated, so the logger can capture `req.user.id`/`accountId` for free. The tradeoff: requests that fail auth (401 from auth.js:10) won't hit this logger and get no log line — if you want those logged too (useful for spotting credential-stuffing against `/accounts/:id`), put a logger before `sessionUser` as well, or log the 401 inside auth.js itself.

**2. Capture the response, not just the request**

Status code and duration aren't known until the response finishes, so hook `res.on('finish')`:

```js
function requestLogger(req, res, next) {
  const start = process.hrtime.bigint();
  res.on('finish', () => {
    const ms = Number(process.hrtime.bigint() - start) / 1e6;
    log({
      method: req.method,
      path: req.route ? req.baseUrl + req.route.path : req.path,
      status: res.statusCode,
      ms,
      userId: req.user && req.user.id,
      accountId: req.user && req.user.accountId,
      targetId: req.params.id,   // the id being mutated
    });
  });
  next();
}
```

